package mz.bam.seeky.android;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.io.*;import java.util.*;import java.util.zip.*;
/** Portable offline notebook backup. Restore appends in a transaction and remaps every relation. */
final class StudyBackup {
 static final long MAX=536870912L;
 static void write(Context context,StudyStore db,OutputStream stream)throws Exception{JSONObject root=new JSONObject();root.put("format","seeky-studies-2");root.put("created",System.currentTimeMillis());JSONObject tables=new JSONObject();List<StudyStore.Row> materials=null;SQLiteDatabase sql=db.getReadableDatabase();sql.beginTransaction();try{for(String t:StudyStore.TABLES){if(db.count(t,null,null)>10000)throw new IOException("Mais de 10000 registos em "+t+". Exporte por outro meio antes de continuar.");List<StudyStore.Row> rows=db.rows(t,null,null,"id",10000);JSONArray data=new JSONArray();for(StudyStore.Row row:rows){JSONObject item=new JSONObject();for(Map.Entry<String,String> v:row.entrySet())if(!v.getKey().equals("path"))item.put(v.getKey(),v.getValue());data.put(item);}if(t.equals("materials"))materials=rows;tables.put(t,data);}root.put("tables",tables);root.put("app_state",StudyState.capture(context,materials));try(ReaderStore reader=new ReaderStore(context)){JSONObject rd=new JSONObject();for(String t:new String[]{"draft","bookmark"}){JSONArray values=new JSONArray();for(StudyStore.Row material:materials){String uri=StudyFileProvider.uri(context,material.id()).toString();try(Cursor c=reader.getReadableDatabase().query(t,null,"uri=?",new String[]{uri},null,null,null)){while(c.moveToNext()){JSONObject v=new JSONObject();v.put("material_id",material.id());for(int i=0;i<c.getColumnCount();i++)if(!c.getColumnName(i).equals("uri")&&!c.getColumnName(i).equals("id"))v.put(c.getColumnName(i),c.getString(i));values.put(v);}}}rd.put(t,values);}root.put("reader",rd);}sql.setTransactionSuccessful();}finally{sql.endTransaction();}
  byte[] manifest=root.toString().getBytes("UTF-8");if(manifest.length>8388608)throw new IOException("Caderno acima do limite de 8 MB de metadados.");try(ZipOutputStream out=new ZipOutputStream(stream)){out.putNextEntry(new ZipEntry("study.json"));out.write(manifest);out.closeEntry();long total=manifest.length;for(StudyStore.Row row:materials){File f=new File(row.s("path"));if(!f.isFile()||!StudyFiles.hash(f).equals(row.s("hash")))throw new IOException("Material alterado ou indisponível: "+row.s("title"));total+=f.length();if(total>MAX)throw new IOException("Cópia acima de 512 MB; reduza a biblioteca antes de exportar.");out.putNextEntry(new ZipEntry("materials/"+row.id()));try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}out.closeEntry();}}}
 static int restore(Context c,StudyStore db,File archive)throws Exception{List<File> created=new ArrayList<>();boolean committed=false;Map<Long,Long> courses=new HashMap<>(),subjects=new HashMap<>(),materials=new HashMap<>(),cards=new HashMap<>();courses.put(0L,0L);subjects.put(0L,0L);materials.put(0L,0L);cards.put(0L,0L);JSONObject readerData;int imported=0;
 try(ZipFile zip=new ZipFile(archive)){if(zip.size()>11000)throw new IOException("Demasiadas partes.");ZipEntry manifest=zip.getEntry("study.json");if(manifest==null)throw new IOException("Não é uma cópia de Estudos do Seeky.");byte[] json;try(InputStream in=zip.getInputStream(manifest)){json=ContentText.read(in,8388609);}if(json.length>8388608)throw new IOException("Metadados demasiado grandes.");String text=new String(json,"UTF-8");JsonBudget.check(text,12,150000);JSONObject root=new JSONObject(text);if(!Arrays.asList("seeky-studies-1","seeky-studies-2").contains(root.optString("format")))throw new IOException("Formato de cópia incompatível.");JSONObject tables=root.getJSONObject("tables");readerData=root.optJSONObject("reader");JSONArray sourceMaterials=tables.getJSONArray("materials");List<Long> archiveIds=new ArrayList<>();for(int i=0;i<sourceMaterials.length();i++)archiveIds.add(sourceMaterials.getJSONObject(i).getLong("id"));StudyFiles.validateArchive(zip,archiveIds);
 SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(String t:StudyStore.TABLES){JSONArray rows=tables.optJSONArray(t);if(rows==null){if(t.equals("practice")||t.equals("study_trash")||t.equals("courses")&&root.optString("format").equals("seeky-studies-1"))continue;throw new IOException("Falta uma tabela da cópia.");}if(rows.length()>10000)throw new IOException("Demasiados registos em "+t);Set<Long> ids=new HashSet<>();Set<String> allowed=new HashSet<>();try(Cursor schema=sql.rawQuery("PRAGMA table_info("+t+")",null)){while(schema.moveToNext())allowed.add(schema.getString(1));}for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);long old=row.getLong("id");if(old<=0||!ids.add(old))throw new IOException("Identificador inválido ou repetido.");validate(t,row);ContentValues v=new ContentValues();Iterator<String> keys=row.keys();while(keys.hasNext()){String k=keys.next();if(k.equals("id"))continue;if(!allowed.contains(k))throw new IOException("Campo desconhecido: "+k);String value=row.getString(k);if(value.length()>1048576)throw new IOException("Campo demasiado extenso.");v.put(k,value);}if(v.containsKey("course"))v.put("course",mapped(courses,row.optLong("course")));if(v.containsKey("subject"))v.put("subject",mapped(subjects,row.optLong("subject")));if(v.containsKey("material"))v.put("material",mapped(materials,row.optLong("material")));if(v.containsKey("card"))v.put("card",mapped(cards,row.optLong("card")));if(v.containsKey("token"))v.put("token",UUID.randomUUID().toString());
 if(t.equals("study_trash")){JSONObject nested=payload(row.getString("payload"));remapPayload(nested,subjects,materials);v.put("payload",nested.toString());}
 if(t.equals("practice")){if(db.count("practice",null,null)>0)throw new IOException("Já existe um teste em pausa neste telemóvel. Conclua-o ou descarte-o antes de importar outra cópia.");JSONObject nested=payload(row.getString("payload"));nested.put("group",subjects.containsKey(nested.optLong("group"))?subjects.get(nested.optLong("group")):0);JSONArray queue=nested.getJSONArray("queue");for(int n=0;n<queue.length();n++)remapPayload(queue.getJSONObject(n),subjects,materials);v.put("payload",nested.toString());}

 if(t.equals("materials")){java.util.List<StudyStore.Row> existing=db.rows("materials","subject=? AND hash=?",new String[]{""+mapped(subjects,row.optLong("subject")),row.getString("hash")},null,1);if(!existing.isEmpty()){StudyStore.Row match=existing.get(0);File retained=new File(match.s("path"));if(!retained.isFile()||!StudyFiles.hash(retained).equals(row.getString("hash")))throw new IOException("Já existe um material indisponível com a mesma identidade. Remova o registo antes de restaurar.");materials.put(old,match.id());continue;}ZipEntry entry=zip.getEntry("materials/"+old);if(entry==null)throw new IOException("Falta um material na cópia.");File file=new File(StudyFileProvider.directory(c),UUID.randomUUID()+"."+StudyFiles.extension(row.getString("name")));created.add(file);String hash;try(InputStream in=zip.getInputStream(entry)){hash=StudyFiles.copy(in,file,134217728,()->false);}if(!hash.equals(row.getString("hash"))||file.length()!=row.getLong("bytes"))throw new IOException("Integridade do material não confere.");long total=0;for(File f:created)total+=f.length();if(total>MAX)throw new IOException("Cópia acima de 512 MB.");v.put("path",file.getPath());}long id=db.save(t,0,v);if(t.equals("courses"))courses.put(old,id);if(t.equals("subjects"))subjects.put(old,id);if(t.equals("materials"))materials.put(old,id);if(t.equals("cards"))cards.put(old,id);imported++;}}sql.setTransactionSuccessful();}finally{sql.endTransaction();}committed=true;
 // Reader annotations are restored only after every material was verified. IDs remain independent.
 if(readerData!=null)try(ReaderStore reader=new ReaderStore(c)){SQLiteDatabase rs=reader.getWritableDatabase();rs.beginTransaction();try{for(String t:new String[]{"draft","bookmark"}){JSONArray arr=readerData.optJSONArray(t);if(arr==null)continue;Set<String> allowed=new HashSet<>();try(Cursor schema=rs.rawQuery("PRAGMA table_info("+t+")",null)){while(schema.moveToNext())allowed.add(schema.getString(1));}for(int i=0;i<arr.length();i++){JSONObject item=arr.getJSONObject(i);long material=mapped(materials,item.getLong("material_id"));ContentValues v=new ContentValues();v.put("uri",StudyFileProvider.uri(c,material).toString());Iterator<String> keys=item.keys();while(keys.hasNext()){String key=keys.next();if(!key.equals("material_id")&&!key.equals("id")&&!key.equals("uri")&&allowed.contains(key))v.put(key,item.getString(key));}rs.insertWithOnConflict(t,null,v,SQLiteDatabase.CONFLICT_IGNORE);}}rs.setTransactionSuccessful();}finally{rs.endTransaction();}}
 return imported;
 }catch(Exception e){if(committed)throw new IOException("Os dados e materiais de Estudos foram importados, mas as anotações do leitor não foram concluídas. Não repita a importação sem verificar os registos já acrescentados. Detalhe: "+e.getMessage(),e);throw e;}finally{if(!committed)for(File f:created){f.delete();new File(f.getPath()+".part").delete();}}}
 static void validate(String table,JSONObject row)throws Exception {
 if(table.equals("study_trash")){String original=row.getString("table_name");if(!Arrays.asList("notes","cards","questions","tasks").contains(original))throw new IOException("Item eliminado inválido.");validate(original,payload(row.getString("payload")));}
 if(table.equals("practice")){JSONObject practice=payload(row.getString("payload"));if(practice.getJSONArray("queue").length()<1||practice.getJSONArray("queue").length()>20||practice.getInt("at")<0||practice.getInt("at")>practice.getJSONArray("queue").length())throw new IOException("Teste em pausa inválido.");}
 if(table.equals("courses")){StudySchedule.valid(row.getString("title"),120,"Curso");if(row.optString("description").length()>2000)throw new IOException("Descrição do curso demasiado longa.");}
 if(table.equals("subjects")){StudySchedule.valid(row.getString("title"),80,"Disciplina");if((row.has("course")?row.getLong("course"):0)<0||!Arrays.asList("module","subject").contains(row.optString("kind","subject")))throw new IOException("Módulo inválido.");}
 if(table.equals("materials")){StudySchedule.valid(row.getString("title"),240,"Título");StudySchedule.valid(row.getString("name"),240,"Nome");if(!row.getString("hash").matches("[a-f0-9]{64}")||row.getLong("bytes")<0||row.getLong("bytes")>134217728||row.getInt("progress")<0||row.getInt("progress")>100)throw new IOException("Material inválido.");}
 if(table.equals("notes")){StudySchedule.valid(row.getString("title"),200,"Título");StudySchedule.valid(row.getString("body"),200000,"Apontamento");}
 if(table.equals("cards")){StudySchedule.valid(row.getString("front"),5000,"Pergunta");StudySchedule.valid(row.getString("back"),20000,"Resposta");if(row.getInt("interval")<0||row.getInt("interval")>180||row.getInt("reps")<0||row.getInt("lapses")<0||row.getInt("suspended")<0||row.getInt("suspended")>1)throw new IOException("Cartão inválido.");}
 if(table.equals("questions")){StudySchedule.valid(row.getString("prompt"),5000,"Pergunta");StudySchedule.valid(row.getString("answer"),20000,"Resposta");int kind=row.getInt("kind");JSONArray options=new JSONArray(row.getString("choices"));if(kind!=0&&kind!=1||kind==1&&(options.length()!=4||row.getInt("correct")<0||row.getInt("correct")>3))throw new IOException("Pergunta inválida.");}
 if(table.equals("tasks")&&(row.getInt("priority")<0||row.getInt("priority")>2||row.getInt("estimate")<1||row.getInt("estimate")>480||row.getInt("done")<0||row.getInt("done")>1))throw new IOException("Tarefa inválida.");
 if(table.equals("sessions")&&(row.getLong("seconds")<0||row.getLong("seconds")>7200||!Arrays.asList("Foco","Pausa").contains(row.getString("type"))))throw new IOException("Sessão inválida.");
 if(table.equals("reviews")&&(row.getInt("grade")<0||row.getInt("grade")>3))throw new IOException("Revisão inválida.");
 if(table.equals("quiz_runs")&&(row.getInt("total")<1||row.getInt("correct")<0||row.getInt("correct")>row.getInt("total")||row.getInt("self_count")<0||row.getInt("self_count")>row.getInt("total")))throw new IOException("Resultado inválido.");
 }
 static JSONObject payload(String text)throws Exception{if(text.length()>1048576)throw new IOException("Estado de estudo demasiado extenso.");JsonBudget.check(text,12,2000);return new JSONObject(text);}
 static void remapPayload(JSONObject row,Map<Long,Long> subjects,Map<Long,Long> materials)throws Exception{if(row.has("subject"))row.put("subject",String.valueOf(subjects.containsKey(row.getLong("subject"))?subjects.get(row.getLong("subject")):0));if(row.has("material"))row.put("material",String.valueOf(materials.containsKey(row.getLong("material"))?materials.get(row.getLong("material")):0));}
 static long mapped(Map<Long,Long> map,long old)throws IOException{Long n=map.get(old);if(n==null)throw new IOException("Relação ausente na cópia.");return n;}
}
